"""Synthetic test data. Every identity here is generated by Faker (or by the
format rules below) - no real person's data is ever used in tests."""

from __future__ import annotations

import csv
import datetime as dt
import io
import random
import string
from dataclasses import dataclass, field
from email.message import EmailMessage
from email.utils import format_datetime, formataddr, make_msgid

from faker import Faker

MBI_ALPHA = "ACDEFGHJKMNPQRTUVWXY"  # letters allowed in a Medicare MBI (no S, L, O, I, B, Z)


def luhn_check_digit(digits: str) -> str:
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 0:
            d = d * 2 - 9 if d > 4 else d * 2
        total += d
    return str((10 - total % 10) % 10)


@dataclass
class Person:
    first: str
    last: str
    name: str
    email: str
    phone: str
    fax: str
    ssn: str
    mrn: str
    member_id: str
    mbi: str
    medicaid: str
    account: str
    npi: str
    dea: str
    state_license: str
    vin: str
    plate: str
    device_serial: str
    mac: str
    url: str
    ip: str
    ipv6: str
    dob: dt.date
    visit: dt.date
    street: str
    city: str
    state: str
    zip: str
    username: str
    handle: str
    claim: str
    case: str
    fingerprint: str
    voiceprint: str
    employer: str
    relative: str
    old_age: int
    extra: dict = field(default_factory=dict)


class Synth:
    def __init__(self, seed: int = 1234):
        self.fake = Faker("en_US")
        self.fake.seed_instance(seed)
        self.rng = random.Random(seed)

    def digits(self, n: int) -> str:
        return "".join(self.rng.choice(string.digits) for _ in range(n))

    def letters(self, n: int) -> str:
        return "".join(self.rng.choice(string.ascii_uppercase) for _ in range(n))

    def mbi(self) -> str:
        r = self.rng
        an = MBI_ALPHA + string.digits
        s = (r.choice("123456789") + r.choice(MBI_ALPHA) + r.choice(an) + r.choice(string.digits)
             + r.choice(MBI_ALPHA) + r.choice(an) + r.choice(string.digits)
             + r.choice(MBI_ALPHA) + r.choice(MBI_ALPHA) + r.choice(string.digits) + r.choice(string.digits))
        return s if r.random() < 0.5 else f"{s[:4]}-{s[4:7]}-{s[7:]}"

    def npi(self) -> str:
        base = self.rng.choice("12") + self.digits(8)
        return base + luhn_check_digit("80840" + base)

    def dea(self, last: str) -> str:
        d = [int(c) for c in self.digits(6)]
        check = (d[0] + d[2] + d[4] + 2 * (d[1] + d[3] + d[5])) % 10
        return self.rng.choice("ABFGM") + last[0].upper() + "".join(map(str, d)) + str(check)

    def mrn(self) -> str:
        return self.rng.choice([self.digits(7), self.digits(8), "MR" + self.digits(6), "A" + self.digits(7),
                                f"{self.digits(3)}-{self.digits(2)}-{self.digits(4)}"])

    def member_id(self) -> str:
        return self.rng.choice([self.letters(3) + self.digits(9), "W" + self.digits(9), self.letters(2) + self.digits(8)])

    def person(self) -> Person:
        f = self.fake
        first, last = f.first_name(), f.last_name()
        dob = f.date_of_birth(minimum_age=18, maximum_age=85)
        return Person(
            first=first, last=last, name=f"{first} {last}",
            email=f"{first.lower()}.{last.lower()}{self.digits(2)}@{f.free_email_domain()}",
            phone=f.phone_number(), fax=f"({self.digits(3)}) {self.digits(3)}-{self.digits(4)}", ssn=f.ssn(),
            mrn=self.mrn(), member_id=self.member_id(), mbi=self.mbi(), medicaid=self.letters(2) + self.digits(6) + self.letters(1),
            account=self.digits(self.rng.choice([8, 10, 12])), npi=self.npi(), dea=self.dea(last),
            state_license=self.rng.choice(["MD", "RN", "PA"]) + self.digits(6),
            vin=f.vin(), plate=f.license_plate(), device_serial=f"SN{self.letters(2)}{self.digits(7)}",
            mac=f.mac_address().upper(), url=f"https://{f.domain_name()}/patients/{self.digits(5)}",
            ip=f.ipv4_public(), ipv6=f.ipv6(), dob=dob,
            visit=f.date_between(dt.date(2019, 1, 1), dt.date(2024, 12, 31)),
            street=f.street_address(), city=f.city(), state=f.state_abbr(include_territories=False), zip=f.zipcode(),
            username=f.user_name() + self.digits(2), handle="@" + f.user_name(), claim=f"CLM-{self.digits(4)}-{self.digits(5)}",
            case=f"{self.rng.randint(2018, 2024)}-{self.digits(5)}", fingerprint=f"FP-{self.digits(6)}",
            voiceprint=f"VP{self.digits(8)}", employer=f.company(), relative=f"{f.first_name()} {last}",
            old_age=self.rng.randint(90, 104),
        )

    # ------------------------------------------------------------ text
    def date_text(self, d: dt.date) -> str:
        return self.rng.choice([
            d.strftime("%m/%d/%Y"), f"{d.month}/{d.day}/{d.year}", d.strftime("%B %d, %Y"), f"{d:%b} {d.day}, {d.year}",
            d.isoformat(), d.strftime("%d %B %Y"), f"{d.month}/{d.day}/{d:%y}", d.strftime("%A, %B %d, %Y"),
        ])

    def note(self, p: Person) -> str:
        return (f"Patient {p.name} (MRN {p.mrn}, DOB {self.date_text(p.dob)}) was seen on {self.date_text(p.visit)}.\n"
                f"Address: {p.street}, {p.city}, {p.state} {p.zip}. Phone {p.phone}, fax {p.fax}.\n"
                f"Insurance member ID: {p.member_id}. SSN {p.ssn}. Her husband {p.relative} works at {p.employer}.\n"
                f"Portal username: {p.username}. Email {p.email}.\n")

    # ------------------------------------------------------------ email
    def eml(self, sender: Person, to: Person, *, reply_to: EmailMessage | None = None, html: bool = True,
            csv_attachment: bool = False, image_attachment: bool = False, nested: EmailMessage | None = None,
            audio_attachment: bool = False) -> EmailMessage:
        msg = EmailMessage()
        msg["From"] = formataddr((sender.name, sender.email))
        msg["To"] = formataddr((to.name, to.email))
        msg["Cc"] = formataddr((f"{sender.last}, {sender.first}", f"alt.{sender.email}"))
        msg["Subject"] = (f"Re: {reply_to['Subject']}" if reply_to is not None
                          else f"Follow-up for {to.name} - visit {self.date_text(to.visit)}")
        msg["Date"] = format_datetime(dt.datetime(2022, self.rng.randint(1, 12), self.rng.randint(1, 28), 9, 30,
                                                  tzinfo=dt.timezone.utc))
        msg["Message-ID"] = make_msgid(domain="mail." + self.fake.domain_name())
        msg["Received"] = f"from mail.example.net ({sender.ip}) by mx.example.org; {msg['Date']}"
        msg["X-Originating-IP"] = f"[{sender.ip}]"
        if reply_to is not None:
            msg["In-Reply-To"] = reply_to["Message-ID"]
            msg["References"] = reply_to["Message-ID"]
        body = f"Hi {to.first},\n\n{self.note(to)}\nThanks,\n{sender.first}\n{sender.phone}\n"
        msg.set_content(body)
        if html:
            msg.add_alternative(
                f"<html><body><p>Hi <b>{to.first}</b>,</p><p>{self.note(to).replace(chr(10), '<br>')}</p>"
                f"<p>Profile: <a href=\"{to.url}\">{to.url}</a> - <a href=\"mailto:{to.email}\">{to.email}</a></p>"
                f"<p>Thanks,<br>{sender.name}</p></body></html>", subtype="html")
        if csv_attachment:
            msg.add_attachment(self.csv_text([to, sender]).encode(), maintype="text", subtype="csv",
                               filename=f"{to.last}_patients.csv")
        if image_attachment:
            msg.add_attachment(b"\x89PNG\r\n\x1a\n" + bytes(64), maintype="image", subtype="png",
                               filename=f"{to.first}_photo.png")
        if audio_attachment:
            msg.add_attachment(b"RIFF" + bytes(64), maintype="audio", subtype="wav", filename="voicemail.wav")
        if nested is not None:
            msg.add_attachment(nested)
        return msg

    # ------------------------------------------------------------ tables
    HEADERS = ["Patient Name", "First Name", "Last Name", "DOB", "Age", "Email", "Phone", "Fax", "SSN", "MRN",
               "Member ID", "Account Number", "NPI", "Street Address", "City", "State", "ZIP", "Visit Date",
               "Employer", "Notes", "Copay", "Status"]

    def row(self, p: Person) -> list:
        return [p.name, p.first, p.last, p.dob.isoformat(), str(self.rng.choice([34, 57, p.old_age])), p.email,
                p.phone, p.fax, p.ssn, p.mrn, p.member_id, p.account, p.npi, p.street, p.city, p.state, p.zip,
                p.visit.strftime("%m/%d/%Y"), p.employer,
                f"Spoke with {p.relative} on {self.date_text(p.visit)}; call back at {p.phone}.",
                f"{self.rng.choice([10, 20, 35])}.00", self.rng.choice(["Active", "Closed", "Pending"])]

    def csv_text(self, people: list[Person], delimiter: str = ",") -> str:
        buf = io.StringIO()
        w = csv.writer(buf, delimiter=delimiter, lineterminator="\r\n")
        w.writerow(self.HEADERS)
        for p in people:
            w.writerow(self.row(p))
        return buf.getvalue()

    def xlsx_bytes(self, people: list[Person]) -> bytes:
        from openpyxl import Workbook
        from openpyxl.comments import Comment
        from openpyxl.styles import Font, PatternFill

        wb = Workbook()
        ws = wb.active
        ws.title = "Patients"
        ws.append(self.HEADERS)
        for c in ws[1]:
            c.font = Font(bold=True, color="FFFFFF")
            c.fill = PatternFill("solid", fgColor="1F4E78")
        for p in people:
            r = self.row(p)
            r[3] = dt.datetime.combine(p.dob, dt.time())
            r[17] = dt.datetime.combine(p.visit, dt.time())
            ws.append(r)
            ws.cell(ws.max_row, 4).number_format = "mm/dd/yyyy"
            ws.cell(ws.max_row, 18).number_format = "mm/dd/yyyy"
        ws.column_dimensions["A"].width = 28
        ws["T2"].comment = Comment(f"Confirmed by {people[0].relative} at {people[0].phone}", people[-1].name)
        ws["A2"].hyperlink = people[0].url
        summary = wb.create_sheet("Summary")
        summary["A1"] = f"Report prepared by {people[0].name}"
        summary["A2"] = "Total patients"
        summary["B2"] = len(people)
        summary["B3"] = "=B2*2"
        wb.properties.creator = people[0].name
        wb.properties.lastModifiedBy = people[1].name if len(people) > 1 else people[0].name
        wb.properties.title = f"Patient list for {people[0].employer}"
        out = io.BytesIO()
        wb.save(out)
        return out.getvalue()
